WITH filtered AS (SELECT *, ROUND(cost, 2) AS cost_rounded FROM products WHERE launch_date >= TO_DATE('2023-08-17')), ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY supplier_id ORDER BY price DESC, id) AS rn FROM filtered) t WHERE rn = 1), deduped AS (SELECT * FROM ranked QUALIFY RANK() OVER (PARTITION BY supplier_id ORDER BY rn DESC) = 1), scored AS (SELECT *, LAG(cost, 2) OVER (PARTITION BY supplier_id ORDER BY cost, id) AS prev_cost, ROW_NUMBER() OVER (ORDER BY launch_date DESC, id) AS row_seq, NTILE(3) OVER (ORDER BY stock_qty, id) AS stock_qty_bucket, ROW_NUMBER() OVER (ORDER BY rn DESC, id) AS seq_no FROM deduped WHERE cost_rounded >= 30) SELECT category, DATE_TRUNC('QUARTER', launch_date) AS quarter_start, STDDEV_SAMP(stock_qty) AS stock_qty_stddev, COUNT(*) FILTER (WHERE brand = 'Stark') AS stark_rows, SIZE(COLLECT_SET(category)) AS num_categories, PERCENT_RANK() OVER (PARTITION BY category ORDER BY SIZE(COLLECT_SET(category)) DESC) AS num_categories_percent_rank FROM scored GROUP BY category, DATE_TRUNC('QUARTER', launch_date) ORDER BY stock_qty_stddev NULLS FIRST;
